<?php
namespace App\Http\Controllers\Api;use App\Models\Doctor;use App\Models\HomeVisitRequest;use App\Models\Patient;use App\Services\Notification\ClinicNotificationDispatcher;use Illuminate\Http\Request;use Illuminate\Support\Str;
class HomeVisitController{private function patient(){return Patient::where('user_id',auth()->id())->firstOrFail();}private function owned(string $n){$q=HomeVisitRequest::with(['doctor.user','patient.user'])->where('request_number',$n);if(!auth()->user()->isAdmin()){$p=Patient::where('user_id',auth()->id())->first();$d=Doctor::where('user_id',auth()->id())->first();$q->where(fn($x)=>$x->where('patient_id',$p?->id)->orWhere('doctor_id',$d?->id));}return $q->firstOrFail();}private function metrics($v){if(!$v->doctor_latitude||!$v->doctor_longitude)return[null,null];$r=6371;$a=deg2rad($v->patient_latitude-$v->doctor_latitude);$b=deg2rad($v->patient_longitude-$v->doctor_longitude);$h=sin($a/2)**2+cos(deg2rad($v->doctor_latitude))*cos(deg2rad($v->patient_latitude))*sin($b/2)**2;$km=2*$r*asin(min(1,sqrt($h)));return[round($km,2),(int)ceil($km/25*60)];}public function store(Request $r){$d=$r->validate(['doctor_id'=>'nullable|exists:doctors,id','address'=>'required|string|max:1000','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','scheduled_at'=>'nullable|date','symptoms'=>'nullable|string|max:3000','contact_phone'=>'required|string|max:30']);$doctor=!empty($d['doctor_id'])?Doctor::with('user')->find($d['doctor_id']):null;abort_if($doctor&&!$doctor->offers_home_visit,422,'ویزیت منزل برای پزشک فعال نیست');$v=HomeVisitRequest::create(['patient_id'=>$this->patient()->id,'request_number'=>'HV-'.strtoupper(Str::random(10)),'patient_latitude'=>$d['latitude'],'patient_longitude'=>$d['longitude'],'amount'=>$doctor?->home_visit_fee??0,...collect($d)->except(['latitude','longitude'])->all()]);$notify=app(ClinicNotificationDispatcher::class);$notify->send($doctor?->clinic_id,'home_visit.created',auth()->user(),['number'=>$v->request_number],'پزشک در منزل','درخواست {number} ثبت شد.');if($doctor?->user)$notify->send($doctor->clinic_id,'home_visit.assigned',$doctor->user,['number'=>$v->request_number],'درخواست ویزیت منزل','درخواست {number} برای شما ثبت شد.');return response()->json(['success'=>true,'data'=>$v],201);}public function index(){return response()->json(['success'=>true,'data'=>$this->patient()->homeVisitRequests()->with('doctor.user')->latest()->paginate(15)]);}public function show(string $n){$v=$this->owned($n);[$km,$eta]=$this->metrics($v);return response()->json(['success'=>true,'data'=>array_merge($v->toArray(),['distance_km'=>$km,'eta_minutes'=>$eta])]);}public function updateLocation(Request $r,string $n){$v=$this->owned($n);$doctor=Doctor::where('user_id',auth()->id())->first();abort_unless(auth()->user()->isAdmin()||$doctor?->id===$v->doctor_id,403);$d=$r->validate(['latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','status'=>'nullable|in:assigned,on_the_way,arrived,completed']);$v->update(['doctor_latitude'=>$d['latitude'],'doctor_longitude'=>$d['longitude'],'last_location_at'=>now(),'status'=>$d['status']??$v->status]);if($v->patient?->user)app(ClinicNotificationDispatcher::class)->send($v->doctor?->clinic_id,'home_visit.location_updated',$v->patient->user,['number'=>$v->request_number],'موقعیت پزشک','موقعیت پزشک درخواست {number} به‌روزرسانی شد.');return $this->show($n);}}
